def pairwise_q(clean_i, clean_j, pairs):
    n = min(len(clean_i), len(clean_j), len(pairs))
    a = b = c = d = 0
    for idx in range(n):
        gt = pairs[idx]["ground_truth_winner"]
        ci = clean_i[idx].get("winner", "tie") == gt
